const baseUrl = 'http://localhost:5026/api';

export const serverCalls = {

    items: async () => {
        const response = await fetch(`${baseUrl}/items`);
        return await response.json();
    },

    notamon: async () => {
        const response = await fetch(`${baseUrl}/notamon`);
        return await response.json();
    },

    singleNotamon: async (notamonId) => {
        const response = await fetch(`${baseUrl}/notamon/${notamonId}`);
        return await response.json();
    },

    status: async () => {
        const response = await fetch(`${baseUrl}/status`);
        return await response.json();
    },

    typeEffectiveness: async () => {
        const response = await fetch(`${baseUrl}/typeEffectiveness`);
        return await response.json();
    },

    vaults: async () => {
        const response = await fetch(`${baseUrl}/vault.json`);
        return await response.json();
    },

    keys: async () => {
        const response = await fetch(`${baseUrl}/key.json`);
        let data = await response.json();
        return data;    
    }

}
